-- cenário: não precisa mudar nada daqui até a linha em branco
PRAGMA foreign_keys = ON;

CREATE TABLE ticket (id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, categoria TEXT NOT NULL);
INSERT INTO ticket (id, titulo, categoria) VALUES (1, 'impressora', 'hardware'), (2, 'vpn', 'rede');

CREATE TABLE prazo_categoria (
  id INTEGER PRIMARY KEY,
  categoria TEXT NOT NULL UNIQUE,
  horas INTEGER NOT NULL
);

-- O prazo aplicado fica no ticket: mudar a categoria depois nao reescreve o historico.
CREATE TABLE prazo_ticket (
  id INTEGER PRIMARY KEY,
  ticket_id INTEGER NOT NULL UNIQUE REFERENCES ticket (id),
  horas INTEGER NOT NULL,
  registrado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
